  options:["労働保険審査官","3倍","2か月","同額","厚生労働大臣","社会保険審査官","社会保険審査会","2年","雇用保険審査官","労働政策審議会","都道府県労働局長","労働保険審査会","3年","60日","6か月","3か月","2倍","1年","5年","5倍"],
